"""Partition Labels — cut when the scan reaches the last occurrence seen so far.

Time: O(n)   Space: O(1)
"""
from typing import List


class Solution:
    def partitionLabels(self, s: str) -> List[int]:
        last = {ch: i for i, ch in enumerate(s)}
        out, start, end = [], 0, 0
        for i, ch in enumerate(s):
            end = max(end, last[ch])
            if i == end:
                out.append(end - start + 1)
                start = i + 1
        return out
